create extension if not exists "uuid-ossp";
create table if not exists profiles(id uuid primary key references auth.users(id) on delete cascade, username text unique not null, display_name text not null default '', bio text default '', avatar_url text, is_private boolean not null default false, created_at timestamptz not null default now());
create table if not exists posts(id uuid primary key default uuid_generate_v4(), user_id uuid not null references profiles(id) on delete cascade, caption text default '', visibility text not null default 'public', created_at timestamptz not null default now());
create table if not exists media(id uuid primary key default uuid_generate_v4(), post_id uuid references posts(id) on delete cascade, owner_id uuid not null references profiles(id) on delete cascade, url text not null, media_type text not null, width int, height int, created_at timestamptz not null default now());
create table if not exists comments(id uuid primary key default uuid_generate_v4(), post_id uuid not null references posts(id) on delete cascade, user_id uuid not null references profiles(id) on delete cascade, body text not null, created_at timestamptz not null default now());
create table if not exists likes(post_id uuid not null references posts(id) on delete cascade, user_id uuid not null references profiles(id) on delete cascade, created_at timestamptz not null default now(), primary key(post_id,user_id));
create table if not exists saves(post_id uuid not null references posts(id) on delete cascade, user_id uuid not null references profiles(id) on delete cascade, created_at timestamptz not null default now(), primary key(post_id,user_id));
create table if not exists follows(follower_id uuid not null references profiles(id) on delete cascade, following_id uuid not null references profiles(id) on delete cascade, status text not null default 'accepted', created_at timestamptz not null default now(), primary key(follower_id,following_id));
create table if not exists stories(id uuid primary key default uuid_generate_v4(), user_id uuid not null references profiles(id) on delete cascade, media_url text not null, expires_at timestamptz not null default (now()+interval '24 hours'), created_at timestamptz not null default now());
create table if not exists story_views(story_id uuid not null references stories(id) on delete cascade, user_id uuid not null references profiles(id) on delete cascade, viewed_at timestamptz not null default now(), primary key(story_id,user_id));
create table if not exists conversations(id uuid primary key default uuid_generate_v4(), created_at timestamptz not null default now());
create table if not exists conversation_members(conversation_id uuid not null references conversations(id) on delete cascade, user_id uuid not null references profiles(id) on delete cascade, joined_at timestamptz not null default now(), primary key(conversation_id,user_id));
create table if not exists messages(id uuid primary key default uuid_generate_v4(), conversation_id uuid not null references conversations(id) on delete cascade, sender_id uuid not null references profiles(id) on delete cascade, body text, attachment_url text, status text not null default 'sent', created_at timestamptz not null default now());
create table if not exists message_reactions(message_id uuid not null references messages(id) on delete cascade, user_id uuid not null references profiles(id) on delete cascade, reaction text not null, created_at timestamptz not null default now(), primary key(message_id,user_id));
create table if not exists notifications(id uuid primary key default uuid_generate_v4(), recipient_id uuid not null references profiles(id) on delete cascade, actor_id uuid references profiles(id) on delete set null, kind text not null, entity_id uuid, read_at timestamptz, created_at timestamptz not null default now());
create table if not exists blocks(blocker_id uuid not null references profiles(id) on delete cascade, blocked_id uuid not null references profiles(id) on delete cascade, created_at timestamptz not null default now(), primary key(blocker_id,blocked_id));
create table if not exists reports(id uuid primary key default uuid_generate_v4(), reporter_id uuid not null references profiles(id) on delete cascade, target_type text not null, target_id uuid not null, reason text not null, created_at timestamptz not null default now());
create table if not exists settings(user_id uuid primary key references profiles(id) on delete cascade, message_permissions text default 'followers', notification_likes boolean default true, notification_messages boolean default true, notification_follows boolean default true, updated_at timestamptz not null default now());
create index if not exists posts_user_created on posts(user_id,created_at desc); create index if not exists messages_conversation_created on messages(conversation_id,created_at);

alter table profiles enable row level security; alter table posts enable row level security; alter table media enable row level security; alter table comments enable row level security; alter table likes enable row level security; alter table saves enable row level security; alter table follows enable row level security; alter table stories enable row level security; alter table story_views enable row level security; alter table conversations enable row level security; alter table conversation_members enable row level security; alter table messages enable row level security; alter table message_reactions enable row level security; alter table notifications enable row level security; alter table blocks enable row level security; alter table reports enable row level security; alter table settings enable row level security;

create policy "public profiles" on profiles for select using (not is_private or id=auth.uid());
create policy "own profile insert" on profiles for insert with check (id=auth.uid()); create policy "own profile update" on profiles for update using (id=auth.uid());
create policy "public posts" on posts for select using (visibility='public' or user_id=auth.uid()); create policy "own posts" on posts for all using (user_id=auth.uid()) with check (user_id=auth.uid());
create policy "media readable" on media for select using (true); create policy "own media" on media for all using (owner_id=auth.uid()) with check (owner_id=auth.uid());
create policy "comments readable" on comments for select using (true); create policy "own comments" on comments for insert with check (user_id=auth.uid()); create policy "delete own comments" on comments for delete using (user_id=auth.uid());
create policy "likes readable" on likes for select using (true); create policy "own likes" on likes for all using (user_id=auth.uid()) with check (user_id=auth.uid());
create policy "own saves" on saves for all using (user_id=auth.uid()) with check (user_id=auth.uid());
create policy "follows readable" on follows for select using (true); create policy "follow self" on follows for insert with check (follower_id=auth.uid()); create policy "unfollow self" on follows for delete using (follower_id=auth.uid());
create policy "stories readable" on stories for select using (expires_at>now() or user_id=auth.uid()); create policy "own stories" on stories for all using (user_id=auth.uid()) with check (user_id=auth.uid());
create policy "story views own" on story_views for all using (user_id=auth.uid()) with check (user_id=auth.uid());
create policy "conversation members" on conversation_members for select using (user_id=auth.uid()); create policy "join conversation" on conversation_members for insert with check (user_id=auth.uid());
create policy "member messages" on messages for select using (exists(select 1 from conversation_members cm where cm.conversation_id=messages.conversation_id and cm.user_id=auth.uid())); create policy "send messages" on messages for insert with check (sender_id=auth.uid() and exists(select 1 from conversation_members cm where cm.conversation_id=messages.conversation_id and cm.user_id=auth.uid()));
create policy "own reactions" on message_reactions for all using (user_id=auth.uid()) with check (user_id=auth.uid());
create policy "own notifications" on notifications for select using (recipient_id=auth.uid()); create policy "own notification update" on notifications for update using (recipient_id=auth.uid());
create policy "own blocks" on blocks for all using (blocker_id=auth.uid()) with check (blocker_id=auth.uid());
create policy "own reports" on reports for insert with check (reporter_id=auth.uid());
create policy "own settings" on settings for all using (user_id=auth.uid()) with check (user_id=auth.uid());

create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,username) values(new.id,coalesce(new.raw_user_meta_data->>'username','user_'||substr(new.id::text,1,8))); insert into public.settings(user_id) values(new.id); return new; end; $$;
drop trigger if exists on_auth_user_created on auth.users; create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
